    // Google calls gm_authFailure() when it REJECTS the key: expired, referrer
    // blocked, API not enabled, or billing missing. Without this handler the
    // failure is silent - you just get a grey map. So show a loud banner with
    // the exact checklist.
    window.gm_authFailure = function () {
      var add = function () {
        if (document.getElementById('gm-key-error')) return;
        var d = document.createElement('div');
        d.id = 'gm-key-error';
        d.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:2147483647;' +
          'background:#7f1d1d;color:#fff;padding:10px 18px;text-align:center;' +
          "font:13px/1.55 'Segoe UI',system-ui,sans-serif;" +
          'box-shadow:0 4px 18px rgba(0,0,0,.55)';
        d.innerHTML =
          '<b>\u26A0 Google Maps rejected this API key.</b><br>' +
          'Check in console.cloud.google.com: (1) <i>Maps JavaScript API</i> + ' +
          '<i>Places API</i> enabled, (2) billing linked, (3) this page\u2019s origin ' +
          'allowed under <i>Application restrictions \u2192 HTTP referrers</i>.<br>' +
          'Key in use: <code>' + String(GM_KEY).slice(0, 8) + '\u2026</code>';
        document.body.appendChild(d);
      };
      if (document.body) add(); else document.addEventListener('DOMContentLoaded', add);
    };
  

    // circle radius
    var _radiusCircle = null;

    // ── SUPABASE CONFIG (injected by app.py) ─────────────────────
    var _SB_URL = 'SUPABASE_URL_PLACEHOLDER';
    var _SB_KEY = 'SUPABASE_ANON_KEY_PLACEHOLDER';

    // ── USER LISTINGS FROM SUPABASE ────────────────────────────────────────
    var USER_LISTINGS = [];
    var _userMarkers = [];
    var _carouselIdx = 0;

    // -- GLOBAL STATE FOR PICKING LOCATION ON MAP ----------------
    var selectedLat = null;
    var selectedLng = null;
    var selectedRadius = null;
    
    function parseBhkConfigs(lst) {
      var bhks = (lst.bhk_types || '').split(',').map(function (s) { return s.trim(); }).filter(Boolean);
      var avg = (lst.price_min && lst.price_max)
        ? Math.round((parseInt(lst.price_min) + parseInt(lst.price_max)) / 2)
        : parseInt(lst.price_min || lst.price_max || 0);
      return bhks.map(function (b) {
        return { bhk: b, area: (lst.area_min || '?') + '-' + (lst.area_max || '?') + ' sqft', price: avg, price_str: fmtPrice(avg) };
      });
    }

    function loadUserListings() {
      fetch(_SB_URL + '/rest/v1/project_listings?select=*&order=submitted_at.desc', {
        headers: { 'apikey': _SB_KEY, 'Authorization': 'Bearer ' + _SB_KEY }
      })
        .then(function (r) { return r.json(); })
        .then(function (rows) {
          if (!Array.isArray(rows)) return;
          USER_LISTINGS = [];
          rows.forEach(function (lst) {
            if (!lst.latitude || !lst.longitude) return;
            USER_LISTINGS.push({
              name: lst.project_name || 'New Project',
              lat: parseFloat(lst.latitude),
              lon: parseFloat(lst.longitude),
              locality: lst.locality || 'Pune',
              configs: parseBhkConfigs(lst),
              images: lst.images ? lst.images.split(',').filter(Boolean) : [],
              isUserListing: true,
              verified: lst.verified,
              phone: lst.phone,
              rera: lst.rera_number,
              builder: lst.builder_name,
              description: lst.description,
              status: lst.status,
              possession: lst.possession_date,
              price_min: lst.price_min,
              price_max: lst.price_max,
              amenities: lst.amenities
            });
          });
          renderUserListingMarkers();
        })
        .catch(function (e) { console.warn('User listings load error:', e); });
    }

    function renderUserListingMarkers() {
      _userMarkers.forEach(function (o) { if (o.setMap) o.setMap(null); });
      _userMarkers = [];
      if (!_map || typeof google === 'undefined') return;
      USER_LISTINGS.forEach(function (proj) {
        var div = document.createElement('div');
        div.className = 'user-pin';
        var short = proj.name.length > 16 ? proj.name.substring(0, 14) + '\u2026' : proj.name;
        div.innerHTML =
          '<div class="user-pin-icon">&#x1F3D7;<span class="user-pin-pending">!</span></div>' +
          '<div class="user-pin-label">' + short + '</div>';
        if (proj.verified) div.querySelector('.user-pin-pending').style.display = 'none';
        div.addEventListener('click', function (e) { e.stopPropagation(); showUserListingModal(proj); });
        var overlay = new google.maps.OverlayView();
        overlay._div = null;
        overlay.onAdd = function () {
          overlay._div = div;
          this.getPanes().overlayMouseTarget.appendChild(div);
        };
        overlay.draw = function () {
          var pt = this.getProjection().fromLatLngToDivPixel(new google.maps.LatLng(proj.lat, proj.lon));
          if (pt && overlay._div) {
            overlay._div.style.left = (pt.x - 13) + 'px';
            overlay._div.style.top = (pt.y - 36) + 'px';
            overlay._div.style.position = 'absolute';
          }
        };
        overlay.onRemove = function () {
          if (overlay._div && overlay._div.parentNode) overlay._div.parentNode.removeChild(overlay._div);
          overlay._div = null;
        };
        overlay.setMap(_map);
        _userMarkers.push(overlay);
      });
    }

    function showUserListingModal(proj) {
      _carouselIdx = 0;
      var imgsEl = document.getElementById('ul-images');
      if (proj.images && proj.images.length > 0) {
        var dots = proj.images.map(function (_, i) { return '<div class="cdot' + (i === 0 ? ' active' : '') + '"></div>'; }).join('');
        var imgs = proj.images.map(function (u, i) { return '<img src="' + u + '" class="carousel-img' + (i === 0 ? ' active' : '') + '"/>'; }).join('');
        var nav = proj.images.length > 1
          ? '<button class="carousel-prev" onclick="carouselMove(-1)">&#x2039;</button><button class="carousel-next" onclick="carouselMove(1)">&#x203A;</button>'
          : '';
        imgsEl.innerHTML = '<div class="img-carousel">' + imgs + nav + '<div class="carousel-dots">' + dots + '</div></div>';
      } else {
        imgsEl.innerHTML = '<div style="height:50px;display:flex;align-items:center;justify-content:center;color:#2d3f5e;font-size:0.78rem;margin-bottom:10px;">&#x1F4F7; No photos uploaded yet</div>';
      }
      // Badge
      document.getElementById('ul-pending-badge').style.display = proj.verified ? 'none' : 'inline-flex';
      // Price
      var prMin = parseInt(proj.price_min || 0), prMax = parseInt(proj.price_max || 0);
      var prStr = prMin ? fmtPrice(prMin) + (prMax && prMax !== prMin ? ' \u2013 ' + fmtPrice(prMax) : ' onwards') : 'Price On Request';
      var prEl = document.getElementById('ul-price');
      prEl.textContent = prStr;
      prEl.style.color = priceColor(prMin || prMax);
      // Name / loc
      document.getElementById('ul-name').textContent = proj.name;
      document.getElementById('ul-loc').textContent = '\uD83D\uDCCD ' + proj.locality + ', Pune, Maharashtra';
      // Tags
      var bhks = [];
      (proj.configs || []).forEach(function (c) { if (bhks.indexOf(c.bhk) < 0) bhks.push(c.bhk); });
      document.getElementById('ul-tags').innerHTML =
        bhks.map(function (b) { return '<span class="mtag mtag-bhk">' + b + '</span>'; }).join('') +
        (proj.rera ? '<span class="mtag" style="background:rgba(212,168,67,0.1);color:#d4a843;border:1px solid rgba(212,168,67,0.3);">RERA: ' + proj.rera + '</span>' : '') +
        (proj.status ? '<span class="mtag mtag-type">' + proj.status + '</span>' : '') +
        (proj.verified
          ? '<span class="mtag" style="background:rgba(74,222,128,0.12);color:#4ade80;border:1px solid rgba(74,222,128,0.3);">&#x2713; Verified</span>'
          : '<span class="mtag" style="background:rgba(245,158,11,0.1);color:#f59e0b;border:1px solid rgba(245,158,11,0.3);">&#x23F3; Pending</span>');
      // Grid
      var cells = [];
      if (proj.builder) cells.push(['&#x1F3D7; Builder', proj.builder]);
      if (proj.possession) cells.push(['&#x1F4C5; Possession', proj.possession]);
      if (proj.configs && proj.configs[0]) cells.push(['&#x1F4D0; Area', proj.configs[0].area]);
      if (proj.amenities) cells.push(['&#x2728; Amenities', proj.amenities.split(',').slice(0, 2).join(', ')]);
      document.getElementById('ul-grid').innerHTML = cells.map(function (r) {
        return '<div class="ul-cell"><div class="ul-label">' + r[0] + '</div><div class="ul-value">' + r[1] + '</div></div>';
      }).join('');
      // Description
      document.getElementById('ul-desc').innerHTML = proj.description
        ? '<div class="ul-label">&#x1F4DD; Description</div><div class="ul-value" style="line-height:1.5;font-size:0.78rem;color:#9fafc0;">' + proj.description + '</div>'
        : '';
      // Buttons
      document.getElementById('ul-dir').href = 'https://www.google.com/maps/dir/?api=1&destination=' + proj.lat + ',' + proj.lon + '&travelmode=driving';
      var phone = proj.phone ? proj.phone.replace(/[^0-9+]/g, '') : '';
      var cEl = document.getElementById('ul-contact');
      cEl.href = phone ? 'tel:' + phone : '#';
      cEl.style.display = phone ? 'block' : 'none';
      document.getElementById('ulisting-modal').classList.add('open');
    }

    function closeUListingModal() {
      document.getElementById('ulisting-modal').classList.remove('open');
    }

    function carouselMove(dir) {
      var imgs = document.querySelectorAll('#ul-images .carousel-img');
      var dots = document.querySelectorAll('#ul-images .cdot');
      if (!imgs.length) return;
      imgs[_carouselIdx].classList.remove('active');
      if (dots[_carouselIdx]) dots[_carouselIdx].classList.remove('active');
      _carouselIdx = (_carouselIdx + dir + imgs.length) % imgs.length;
      imgs[_carouselIdx].classList.add('active');
      if (dots[_carouselIdx]) dots[_carouselIdx].classList.add('active');
    }

    document.getElementById('ulisting-modal').addEventListener('click', function (e) {
      if (e.target === this) closeUListingModal();
    });

