    var _listPickingLoc = false;

    function openListForm() {
      document.getElementById('list-modal').classList.add('open');
      document.getElementById('list-form-body').innerHTML = document.getElementById('list-form-body').innerHTML; // reset
    }

    function closeListForm() {
      document.getElementById('list-modal').classList.remove('open');
      _listPickingLoc = false;
    }

    function pickListLocation() {
      // Close form temporarily, let user click map
      closeListForm();
      _listPickingLoc = true;
      var _sl1 = document.getElementById('status-left');
      if (_sl1) { _sl1.textContent = '📍 Click anywhere on the map to set your project location'; _sl1.style.color = '#60a5fa'; }
    }

    // Override map click to handle list location picking
    function handleMapClick(latLng) {
      var lat = typeof latLng.lat === 'function' ? latLng.lat() : latLng.lat;
      var lon = typeof latLng.lng === 'function' ? latLng.lng() : latLng.lon;
      if (_listPickingLoc) {
        document.getElementById('lf-lat').value = lat.toFixed(6);
        document.getElementById('lf-lon').value = lon.toFixed(6);
        var display = document.getElementById('lf-loc-display');
        if (display) {
          display.textContent = '✅ ' + lat.toFixed(5) + '°N, ' + lon.toFixed(5) + '°E — location set!';
          display.className = 'lf-loc-display set';
        }
        _listPickingLoc = false;
        var _sl2 = document.getElementById('status-left');
        if (_sl2) { _sl2.textContent = 'Drag the pin or click map to set your location'; _sl2.style.color = ''; }
        setTimeout(function () { document.getElementById('list-modal').classList.add('open'); }, 300);
        return true;
      }
      if (_buyerPickingLoc) {
        document.getElementById('buyer-lat').value = lat.toFixed(6);
        document.getElementById('buyer-lon').value = lon.toFixed(6);
        var bd = document.getElementById('buyer-loc-display');
        if (bd) {
          bd.textContent = '✅ ' + lat.toFixed(5) + '°N, ' + lon.toFixed(5) + '°E — area set!';
          bd.className = 'lf-loc-display set';
        }
        _buyerPickingLoc = false;
        var _sl3 = document.getElementById('status-left');
        if (_sl3) { _sl3.textContent = 'Drag the pin or click map to set your location'; _sl3.style.color = ''; }
        setTimeout(function () { document.getElementById('buyer-modal').classList.add('open'); }, 300);
        return true;
      }
      return false;
    }

