    function validateListForm() {
      var ok = true;
      // Project name
      var pname = document.getElementById('lf-pname').value.trim();
      var errPname = document.getElementById('err-pname');
      if (!pname) { errPname.style.display = 'block'; ok = false; } else { errPname.style.display = 'none'; }

      // BHK
      var bhks = getSelectedChips('bhk');
      var errBhk = document.getElementById('err-bhk');
      if (bhks.length === 0) { errBhk.style.display = 'block'; ok = false; } else { errBhk.style.display = 'none'; }

      // Phone
      var phone = document.getElementById('lf-phone').value.trim();
      var errPhone = document.getElementById('err-phone');
      if (!phone || phone.replace(/\D/g, '').length < 10) { errPhone.style.display = 'block'; ok = false; } else { errPhone.style.display = 'none'; }

      return ok;
    }

    function submitListForm() {
      if (!validateListForm()) return;

      var btn = document.getElementById('lf-submit-btn');
      btn.disabled = true;
      btn.textContent = '⏳ Submitting...';

      var payload = {
        project_name: document.getElementById('lf-pname').value.trim(),
        total_flats: document.getElementById('lf-total-flats').value || null,
        floors: document.getElementById('lf-floors').value || null,
        locality: document.getElementById('lf-locality').value.trim(),
        latitude: document.getElementById('lf-lat').value || null,
        longitude: document.getElementById('lf-lon').value || null,
        bhk_types: getSelectedChips('bhk').join(', '),
        price_min: document.getElementById('lf-price-min').value || null,
        price_max: document.getElementById('lf-price-max').value || null,
        area_min: document.getElementById('lf-area-min').value || null,
        area_max: document.getElementById('lf-area-max').value || null,
        amenities: getSelectedChips('amenity').join(', '),
        status: document.getElementById('lf-status').value,
        possession_date: document.getElementById('lf-possession').value || null,
        rera_number: document.getElementById('lf-rera').value.trim(),
        rera_verified: document.getElementById('lf-rera-verified').checked,
        gated_society: document.getElementById('lf-gated').checked,
        contact_name: document.getElementById('lf-contact-name').value.trim(),
        phone: document.getElementById('lf-phone').value.trim(),
        email: document.getElementById('lf-email').value.trim(),
        builder_name: document.getElementById('lf-builder').value.trim(),
        description: document.getElementById('lf-desc').value.trim(),
        website: document.getElementById('lf-website').value.trim(),
        submitted_at: new Date().toISOString(),
        source: 'propbot_map',
        verified: false
      };

      // Send to Supabase
      var SUPABASE_URL = _SB_URL;
      var SUPABASE_KEY = _SB_KEY;

      // Upload images first, then save listing
      uploadImagesToSupabase(payload.project_name).then(function (imageUrls) {
        payload.images = imageUrls.join(',');

        fetch(SUPABASE_URL + '/rest/v1/project_listings', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'apikey': SUPABASE_KEY,
            'Authorization': 'Bearer ' + SUPABASE_KEY,
            'Prefer': 'return=minimal'
          },
          body: JSON.stringify(payload)
        })
          .then(function (resp) {
            if (resp.ok || resp.status === 201) {
              showListSuccess();
            } else {
              return resp.text().then(function (t) { throw new Error(t); });
            }
          })
          .catch(function (err) {
            console.error('Submit error:', err);
            try { localStorage.setItem('propbot_pending_' + Date.now(), JSON.stringify(payload)); } catch (e) { }
            showListSuccess(true);
          })
          .finally(function () {
            btn.disabled = false;
            btn.textContent = '🚀 Submit Project Listing';
          });
      }); // close uploadImagesToSupabase.then
    }

    function showListSuccess(offline) {
      // Refresh map pins to include the newly submitted listing
      try { loadUserListings(); } catch (e) { }
      var body = document.getElementById('list-form-body');
      body.innerHTML =
        '<div class="lf-success">' +
        '<div class="lf-success-icon">🎉</div>' +
        '<div class="lf-success-title">Project Submitted Successfully!</div>' +
        '<div class="lf-success-sub">' +
        'Thank you for listing your project on PropBot.<br>' +
        (offline ? 'Your submission is saved and will sync when connected.<br>' : '') +
        'Our team will review and verify it within 24–48 hours.<br><br>' +
        '<strong style="color:#d4a843;">Once verified, it will appear on the map for all users.</strong>' +
        '</div>' +
        '<button onclick="closeListForm()" style="margin-top:20px;background:rgba(212,168,67,0.15);border:1px solid rgba(212,168,67,0.4);color:#d4a843;border-radius:10px;padding:10px 24px;font-size:0.85rem;cursor:pointer;">Close</button>' +
        '</div>';
    }

